def calculate_S(N):
    S = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // (N + 1)
    return S

def target_value(N):
    # The formula is (N^3 - N^2 + 2) / 4
    return (N**3 - N**2 + 2) / 4

results = {}
for N in range(1, 6):
    S_N = calculate_S(N)
    T_N = target_value(N)
    results[N] = {
        "S(N)": S_N,
        "T(N)": T_N,
        "Match": S_N == T_N
    }

for N, res in results.items():
    print(f"N={N}: S(N) = {res['S(N)']}, T(N) = {res['T(N)']}, Match = {res['Match']}")
